<script setup lang="ts">
import {computed,onScopeDispose,ref,shallowRef,watch} from 'vue'
import RuleFunctionCodeEditor from './RuleFunctionCodeEditor.vue'
import type {AutocompleteFetchSuggestions} from 'element-plus'
import {ApiError,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {useDeviceDataPreviewSample,type DeviceDataPreviewSelection} from './use-device-data-preview-sample'
import SubdeviceDataPreviewPicker from './SubdeviceDataPreviewPicker.vue'
import type {SubdeviceDataPreviewSource} from './data-property-preview-api'
import {projectId as activeProject} from '@/core/session'
import {dataStreamParameterNames,dataStreamTemplate,normalizeDataStreamParams,type DataStreamItem} from '../device-types/data-stream-publication-api'
import {dataDownlinkFunctionSource,normalizeDataDownlinkFunction,previewDataDownlinkFunction,downlinkSampleBytes,downlinkPreviewContent,type DataDownlinkFunction,type DataDownlinkPreview} from './data-downlink-function-api'
const props=defineProps<{projectId:string;typeId:string;scopeKey:string;streamIdentifier:string;modelValue?:DataDownlinkFunction;streams:readonly (Pick<DataStreamItem,'identifier'|'mqttTopics'>&{name:string;format:string})[];subdevice?:boolean;disabled?:boolean;validationError?:string;top?:string}>()
const emit=defineEmits<{save:[value:DataDownlinkFunction];cancel:[];busy:[value:boolean]}>()
const deviceSample=useDeviceDataPreviewSample({projectId:()=>props.projectId,typeId:()=>props.typeId,scopeKey:()=>props.scopeKey,streamIdentifier:()=>props.streamIdentifier,disabled:()=>!!props.disabled,physical:true})
const source=ref(props.modelValue?.source??dataDownlinkFunctionSource),protocol=ref(props.modelValue?.protocol??''),target=ref(props.modelValue?.streamIdentifier??''),testShown=ref(false),mode=ref<'HEX'|'TEXT'|'JSON'>('HEX'),sample=ref(''),busy=ref(false),error=ref(''),result=shallowRef<DataDownlinkPreview>()
const legacyPhysical=shallowRef<SubdeviceDataPreviewSource>(),physical=computed(()=>deviceSample.context.value?deviceSample.physical.value:legacyPhysical.value),sampleBusy=ref(false),configurationStreams=computed(()=>deviceSample.context.value?props.streams:props.subdevice?physical.value?.streams??[]:props.streams),previewStreams=computed(()=>deviceSample.context.value?(deviceSample.member.value?.profile.type.deviceKind==='SUB_DEVICE'?physical.value?.streams??[]:deviceSample.member.value?.streams??[]):configurationStreams.value),locked=computed(()=>busy.value||sampleBusy.value||deviceSample.loading.value)
const delayed=ref(props.modelValue?.delaySeconds!==undefined),delaySeconds=ref(String(props.modelValue?.delaySeconds??1))
const simulationParams=ref<Record<string,string>>({}),inputStream=computed(()=>previewStreams.value.find(row=>row.identifier===props.streamIdentifier)),targetStream=computed(()=>previewStreams.value.find(row=>row.identifier===target.value)),inputParameters=computed(()=>inputStream.value?dataStreamParameterNames(inputStream.value):[]),outputParams=computed(()=>result.value?JSON.stringify(JSON.parse(result.value.outputJson)?.params??null):'null')
const targetSuggestions:AutocompleteFetchSuggestions=(query,done)=>done(configurationStreams.value.filter(stream=>stream.identifier.toLowerCase().startsWith(query.toLowerCase())).map(stream=>({value:stream.identifier,name:stream.name})))
const size=computed(()=>new TextEncoder().encode(source.value).length)
const editorOpen=ref(true),formatBusy=ref(false),conflicting=computed(()=>locked.value||formatBusy.value)
let alive=true,generation=0,controller:AbortController|undefined
watch(conflicting,value=>emit('busy',value),{immediate:true,flush:'sync'})
function clear(){generation++;controller?.abort();busy.value=false;error.value='';result.value=undefined}
function close(){if(!locked.value){editorOpen.value=false;formatBusy.value=false;emit('cancel')}}
function save(){if(props.disabled||conflicting.value)return;try{if(delayed.value&&(!/^[1-9][0-9]{0,3}$/.test(delaySeconds.value)||Number(delaySeconds.value)>3600))throw new Error('延迟时间须为1至3600的整数秒');const value=normalizeDataDownlinkFunction({protocol:protocol.value,streamIdentifier:target.value,source:source.value,...(delayed.value?{delaySeconds:Number(delaySeconds.value)}:{})});if(!deviceSample.context.value&&!props.subdevice&&!props.streams.some(s=>s.identifier===value.streamIdentifier))throw new Error('请选择当前类型已发布的目标数据流');if(!deviceSample.context.value&&value.protocol==='TCP'&&targetStream.value&&dataStreamTemplate(targetStream.value))throw new Error('TCP不能使用带参数Topic的目标流');emit('save',value)}catch(cause){error.value=errorMessage(cause)}}
async function preview(){
 if(props.disabled||conflicting.value||props.projectId!==activeProject.value)return
 let bytes:Uint8Array,selection:DeviceDataPreviewSelection|undefined;try{selection=deviceSample.capture();if(selection&&!inputStream.value)throw new Error('样例设备当前发布中没有该输入流');if((selection?selection.member.profile.type.deviceKind==='SUB_DEVICE':props.subdevice)&&(!physical.value||!inputStream.value||!targetStream.value))throw new Error('请选择实际子设备和当前网关已发布的目标流后测试');bytes=downlinkSampleBytes(sample.value,mode.value);if(inputStream.value)normalizeDataStreamParams(inputStream.value,dataStreamTemplate(inputStream.value)?simulationParams.value:undefined);if((inputStream.value&&dataStreamTemplate(inputStream.value)||targetStream.value&&dataStreamTemplate(targetStream.value))&&!targetStream.value)throw new Error('请选择目标数据流后再测试模板参数')}catch(cause){error.value=errorMessage(cause);return}
 const s={generation,epoch:identityEpoch(),project:props.projectId,type:props.typeId,scope:props.scopeKey,stream:props.streamIdentifier,physical:physical.value,selection,previewType:selection?.member.deviceTypeId??props.typeId};controller?.abort();controller=new AbortController();busy.value=true;error.value='';result.value=undefined
 const current=()=>alive&&!props.disabled&&s.generation===generation&&s.epoch===identityEpoch()&&activeProject.value===s.project&&props.projectId===s.project&&props.typeId===s.type&&props.scopeKey===s.scope&&props.streamIdentifier===s.stream&&physical.value===s.physical&&deviceSample.current(s.selection)
 try{const value=await previewDataDownlinkFunction({projectId:s.project,deviceTypeId:s.previewType,scopeKey:s.scope},s.stream,source.value,bytes,current,controller.signal,inputStream.value?{input:inputStream.value,target:targetStream.value,...(s.physical?{sample:s.physical}:{}),...(dataStreamTemplate(inputStream.value)?{params:simulationParams.value}:{})}:undefined,s.selection);if(current())result.value=value}catch(cause){if(current()){error.value=errorMessage(cause);if(cause instanceof ApiError&&[401,403,404].includes(cause.status))emit('cancel')}}finally{if(current())busy.value=false}
}
watch(inputParameters,names=>{simulationParams.value=Object.fromEntries(names.map(name=>[name,'']))},{immediate:true,flush:'sync'})
watch([physical,deviceSample.member],clear,{flush:'sync'})
watch(simulationParams,clear,{deep:true,flush:'sync'})
watch([source,mode,sample,protocol,target,delayed,delaySeconds],clear,{flush:'sync'})
watch([()=>props.projectId,()=>props.typeId,()=>props.scopeKey,()=>props.streamIdentifier,()=>props.disabled],()=>{clear();emit('cancel')})
const dispose=onIdentityChange(()=>{clear();emit('cancel')});onScopeDispose(()=>{alive=false;clear();dispose()})
</script>
<template><el-dialog :model-value="true" title="配置操作" :width="top?'min(1000px,94vw)':'min(920px,94vw)'" :top="top" :lock-scroll="top===undefined" :close-on-click-modal="false" :close-on-press-escape="!disabled&&!busy" :show-close="!disabled&&!busy" :before-close="close" append-to-body>
 <el-form label-position="top" :disabled="disabled||busy" @submit.prevent="save">
  <el-form-item label="云函数"><RuleFunctionCodeEditor v-if="editorOpen" v-model="source" ariaLabel="下行云函数" :disabled="disabled||locked" @busy="formatBusy=$event"/></el-form-item><p v-if="!deviceSample.context.value" class="help">{{size}} / 65536 UTF8字节。函数接收(identifier, data)，可选第三参数options={}。返回{type, msg}生成下行数据，返回null不下发。带参数Topic的运行可从options.params读取上报参数；目标Topic带参数时，须返回{type, msg, params}并明确填写目标的全部参数，固定目标不返回params。</p>
  <el-button link type="primary" :disabled="disabled||conflicting" @click="testShown=!testShown">测试云函数</el-button>
  <section v-if="testShown" class="function-test"><el-form-item v-if="deviceSample.context.value" label="选择模拟的设备"><el-select v-model="deviceSample.sampleDeviceId.value" filterable style="width:100%" aria-label="选择模拟的设备" placeholder="请选择设备" :disabled="disabled||busy"><el-option v-for="member in deviceSample.context.value.members" :key="member.deviceId" :value="member.deviceId" :label="member.name"/></el-select></el-form-item><el-alert v-if="deviceSample.error.value" :title="deviceSample.error.value" type="error" :closable="false"/><SubdeviceDataPreviewPicker v-if="subdevice&&!deviceSample.context.value" :project-id="projectId" :type-id="typeId" :scope-key="scopeKey" :stream-identifier="streamIdentifier" :disabled="disabled||busy" @source="legacyPhysical=$event" @busy="sampleBusy=$event"/><p v-if="!deviceSample.context.value" class="help">使用所选上报数据流立即模拟，不等待延迟时间，不向设备发送数据。</p><el-form-item label="模拟设备上报自定义数据"><el-radio-group v-model="mode" aria-label="下行模拟输入格式"><el-radio value="HEX">HEX</el-radio><el-radio value="TEXT">Plaintext</el-radio><el-radio value="JSON">JSON</el-radio></el-radio-group><el-input v-model="sample" type="textarea" :rows="3" aria-label="下行模拟上报数据"/></el-form-item>
   <template v-if="inputParameters.length"><p>纯模拟Topic参数（不会修改规则或发送数据）</p><el-form-item v-for="name in inputParameters" :key="name" :label="name" required><el-input v-model="simulationParams[name]" :aria-label="'模拟Topic参数 '+name" maxlength="64"/></el-form-item><p>每项为1至64位字母、数字、下划线或横线。</p></template>
   <template v-if="result"><h4>生成的下发自定义数据<span v-if="result.format"> · {{result.format}}</span></h4><p v-if="result.format===null" role="status">函数返回null，不生成下行数据。</p><pre v-else aria-label="生成的下行数据">{{downlinkPreviewContent(result)}}</pre><p v-if="outputParams!=='null'">输出Topic参数：{{outputParams}}</p></template><el-button :loading="busy" :disabled="disabled||conflicting" @click="preview">测试</el-button><p v-if="result" role="status">测试调用成功</p>
  </section>
  <el-form-item label="推送方式"><el-radio-group v-model="protocol" aria-label="下行推送方式"><el-radio value="MQTT">MQTT</el-radio><el-radio value="TCP">TCP</el-radio></el-radio-group></el-form-item>
  <el-form-item label="自定义数据流"><el-autocomplete v-model="target" :fetch-suggestions="targetSuggestions" popper-class="command-autocomplete" style="width:100%" aria-label="下行目标数据流" placeholder="填写自定义数据流标识符"><template #default="{item}"><div class="identifier">{{item.value}}</div><span class="name">{{item.name}}</span></template></el-autocomplete></el-form-item>
  <el-form-item label="是否延迟执行"><el-switch v-model="delayed" aria-label="是否延迟执行"/></el-form-item>
  <el-form-item v-if="delayed" label="延迟时间（秒）"><el-input v-model="delaySeconds" inputmode="numeric" maxlength="4" aria-label="延迟时间（秒）"/><p v-if="!deviceSample.context.value" class="help">1至3600整数秒。从本条上报被接纳时刻起计时，到期后执行函数，不承诺准秒送达。</p></el-form-item>
  <p v-if="subdevice&&!deviceSample.context.value" class="help">通过原上报网关下发原字节，不代表子设备收到或执行。目标标识可显式填写，必须由实际网关原连接的固定发布验证；不从子设备流推测Topic。测试先选实际子设备，再从网关当前发布选择目标；样例不保存进规则。</p><p v-if="!deviceSample.context.value" class="help">{{delayed?'到期后执行函数并下发':'立即执行函数并下发'}}到当前上报设备，推送方式须与原上报连接一致；目标数据流须在原发布中声明，TCP须为该连接绑定的数据流。函数超时或输出格式不符时不下发。</p>
 </el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <el-alert v-if="validationError" :title="validationError" type="warning" :closable="false"/><template #footer><el-form :disabled="false"><el-button :disabled="disabled||locked" @click="close">取消</el-button><el-button type="primary" :disabled="disabled||conflicting" @click="save">保存</el-button></el-form></template>
</el-dialog></template>
<style scoped>.help{font-size:13px;color:var(--el-text-color-secondary);line-height:1.7}.function-test{margin:12px 0 24px;padding:16px;background:var(--el-fill-color-light)}.function-test .el-radio-group{display:flex;margin-bottom:12px}.el-select{width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}.el-form-item{margin-top:20px}:deep(textarea){font-family:ui-monospace,SFMono-Regular,Menlo,monospace}</style>
